      "creator_endscreen/creator_endscreen.html":
        '<div bedrock-style="left: {{getLeft()}}; top: {{getTop()}}; width: {{getWidth()}}; height: {{getHeight()}}">  <div class="creator-endscreen-overlay"></div>  <div class="inactive creator-endscreen-indicator">    <div class="creator-endscreen-dpad"></div>    <div class="first icon icon-player-less"></div>    <div class="creator-endscreen-hint">[[In-video links|An indicator link that reveals the endscreen in-video links.]]</div>  </div>  <div class="active creator-endscreen-indicator">    <div class="first">[[Resume video|An indicator link that hides the endscreen in-video links.]]</div>    <div class="icon icon-player-more"></div>  </div></div>',
