        '<div class="bed-spinner">  <div class="fallback-loading-indicator">[[LOADING...|Indicator that content is loading from the network.]]</div>  <div class=\'loading-indicator\'>    <div class="dot" id="dot1"></div>    <div class="dot" id="dot2"></div>    <div class="dot" id="dot3"></div>    <div class="dot" id="dot4"></div>    <div class="dot" id="dot5"></div>    <div class="dot" id="dot6"></div>    <div class="dot" id="dot7"></div>    <div class="dot" id="dot8"></div>  </div></div>',
